// Ouverture du run agentique en espace bac à sable.
// La mission confiée à l'agent est la MÊME tâche de veille que celle exécutée par le dispositif B
// (condition de comparabilité du protocole § 10.5).
return [{ json: {
  run_namespace: 'sandbox_agent',
  run_ouvert_le: new Date().toISOString(),
  plafond_iterations: 25,
  plafond_appels_modele: 40,
  secteur: 'automobile',
  questions_veille: ['QV1', 'QV2', 'QV3', 'QV4', 'QV5'],
  mission: "Établis l'état actuel du marché automobile mondial pour un décideur de PME sous-traitante de précision. Pour chacune des cinq questions de veille (QV1 santé structurelle de la branche, QV2 demande et débouchés, QV3 dynamique géographique, QV4 dynamique technologique, QV5 impulsions publiques) : identifie les sources officielles pertinentes, collecte les valeurs des trois derniers exercices, calcule les variations, puis publie pour chaque indicateur une valeur datée et sourcée ainsi qu'un commentaire exécutif de 120 mots maximum par question de veille. Tu disposes des outils nécessaires ; tu décides seul de leur usage, de l'ordre des opérations et du moment où le travail est terminé."
} }];

const p = JSON.parse(query);
const v = p.valeurs || [];
if (p.operation === 'variation_pct') { const a = v[v.length-2], b = v[v.length-1]; return String(a ? ((b-a)/a*100).toFixed(2) : 'indéfini'); }
if (p.operation === 'moyenne') { return String(v.reduce((x,y)=>x+y,0)/(v.length||1)); }
if (p.operation === 'pente') { const n=v.length, xs=v.map((_,i)=>i); const mx=xs.reduce((a,b)=>a+b,0)/n, my=v.reduce((a,b)=>a+b,0)/n; const num=xs.map((x,i)=>(x-mx)*(v[i]-my)).reduce((a,b)=>a+b,0); const den=xs.map(x=>(x-mx)**2).reduce((a,b)=>a+b,0); return String(den? num/den : 0); }
return 'opération inconnue';

// Trace d'exécution complète : la seule chose que le scénario C offre en substitut de la traçabilité par statuts du scénario B.
const agent = $('Agent de veille autonome').first().json;
const etapes = agent.intermediateSteps || [];
const outils = {};
for (const e of etapes) {
  const n = e.action?.tool || 'inconnu';
  outils[n] = (outils[n] || 0) + 1;
}
let critique = {};
try { critique = JSON.parse(($json.content?.[0]?.text || '{}').replace(/^```json/i, '').replace(/```$/, '').trim()); } catch (e) { critique = { erreur_parsing: true }; }

return [{ json: {
  run_namespace: 'sandbox_agent',
  clos_le: new Date().toISOString(),
  scenario: 'C',
  nb_iterations: etapes.length,
  plafond_atteint: etapes.length >= 25,
  appels_par_outil: outils,
  referentiel_consulte: Object.keys(outils).some(n => /r.f.rentiel/i.test(n)),
  outil_calcul_utilise: Object.keys(outils).some(n => /calcul/i.test(n)),
  sortie_finale: agent.output ?? null,
  trace_complete: etapes,
  autocritique: critique
} }];
